async function ensureActorPrivateRunThreadLedgers(sql: SqlClient) {
  await sql`
    CREATE OR REPLACE FUNCTION omni_current_actor_scope_v1()
    RETURNS JSONB
    LANGUAGE plpgsql
    STABLE
    SECURITY INVOKER
    SET search_path = pg_catalog, public
    AS $function$
    DECLARE
      raw_scope TEXT;
      actor_scope JSONB;
      actor_count INTEGER;
      distinct_actor_count INTEGER;
    BEGIN
      raw_scope := NULLIF(
        current_setting('omni.actor_scope_v1', TRUE),
        ''
      );
      IF raw_scope IS NULL THEN
        RETURN NULL;
      END IF;
      actor_scope := raw_scope::JSONB;
      IF jsonb_typeof(actor_scope) <> 'object'
        OR actor_scope ->> 'version' <> '1'
        OR actor_scope ->> 'tenantId' IS DISTINCT FROM
          NULLIF(current_setting('omni.tenant_id', TRUE), '')
        OR jsonb_typeof(actor_scope -> 'actorIds') <> 'array'
      THEN
        RETURN NULL;
      END IF;
      actor_count := jsonb_array_length(actor_scope -> 'actorIds');
      IF actor_count NOT BETWEEN 1 AND 8 THEN
        RETURN NULL;
      END IF;
      SELECT count(*), count(DISTINCT actor_id COLLATE "C")
      INTO actor_count, distinct_actor_count
      FROM jsonb_array_elements(actor_scope -> 'actorIds') actor(actor_value)
      CROSS JOIN LATERAL (
        SELECT actor.actor_value #>> '{}' AS actor_id
      ) value
      WHERE jsonb_typeof(actor.actor_value) = 'string'
        AND value.actor_id = btrim(value.actor_id)
        AND char_length(value.actor_id) BETWEEN 1 AND 320;
      IF actor_count <> jsonb_array_length(actor_scope -> 'actorIds')
        OR distinct_actor_count <> actor_count
      THEN
        RETURN NULL;
      END IF;
      RETURN actor_scope;
    EXCEPTION WHEN OTHERS THEN
      RETURN NULL;
    END
    $function$
  `;
  await sql`
    CREATE OR REPLACE FUNCTION omni_actor_scope_v1_allows_validated(
      actor_scope JSONB,
      row_tenant_id TEXT,
      row_actor_id TEXT
    )
    RETURNS BOOLEAN
    LANGUAGE SQL
    IMMUTABLE
    STRICT
    SECURITY INVOKER
    SET search_path = pg_catalog, public
    AS $function$
      SELECT COALESCE(
        actor_scope ->> 'tenantId' = row_tenant_id
        AND EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(actor_scope -> 'actorIds') actor(actor_id)
          WHERE actor.actor_id COLLATE "C" = row_actor_id COLLATE "C"
        ),
        FALSE
      )
    $function$
  `;
  await sql`
    CREATE OR REPLACE FUNCTION omni_actor_scope_v1_allows(
      row_tenant_id TEXT,
      row_actor_id TEXT
    )
    RETURNS BOOLEAN
    LANGUAGE SQL
    STABLE
    SECURITY INVOKER
    SET search_path = pg_catalog, public
    AS $function$
      SELECT public.omni_actor_scope_v1_allows_validated(
        public.omni_current_actor_scope_v1(),
        row_tenant_id,
        row_actor_id
      )
    $function$
  `;

  await sql`
    ALTER TABLE omni_agent_runs
    ADD COLUMN IF NOT EXISTS owner_actor_id TEXT
  `;
  await sql`
    UPDATE omni_agent_runs run
    SET owner_actor_id = COALESCE(
      (
        SELECT NULLIF(btrim(thread.actor_id), '')
        FROM omni_threads thread
        WHERE thread.tenant_id = run.tenant_id
          AND thread.id = run.thread_id
        LIMIT 1
      ),
      NULLIF(btrim(run.continuation #>> '{context,actorId}'), ''),
      (
        SELECT NULLIF(
          btrim(candidate.payload #>> '{_executionScope,initiatingActorId}'),
          ''
        )
        FROM omni_events candidate
        WHERE candidate.tenant_id = run.tenant_id
          AND candidate.stream_id = 'run:' || run.id
          AND candidate.payload ? '_executionScope'
        ORDER BY
          CASE WHEN candidate.type = 'run.scope_bound' THEN 0 ELSE 1 END,
          candidate.seq ASC
        LIMIT 1
      ),
      'quarantine:run:' || left(run.id, 300)
    )
    WHERE run.owner_actor_id IS NULL
  `;
  await sql`
    CREATE OR REPLACE FUNCTION omni_bind_agent_run_owner()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    AS $function$
    DECLARE
      actor_scope JSONB;
    BEGIN
      IF NEW.owner_actor_id IS NOT NULL THEN
        RETURN NEW;
      END IF;
      actor_scope := omni_current_actor_scope_v1();
      IF actor_scope IS NOT NULL THEN
        NEW.owner_actor_id := actor_scope -> 'actorIds' ->>
          (jsonb_array_length(actor_scope -> 'actorIds') - 1);
      END IF;
      IF NEW.owner_actor_id IS NULL AND NEW.thread_id IS NOT NULL THEN
        SELECT thread.actor_id
        INTO NEW.owner_actor_id
        FROM omni_threads thread
        WHERE thread.tenant_id = NEW.tenant_id
          AND thread.id = NEW.thread_id
        LIMIT 1;
      END IF;
      IF NEW.owner_actor_id IS NULL THEN
        RAISE EXCEPTION 'Agent run requires an actor-bound database scope'
          USING ERRCODE = '42501';
      END IF;
      RETURN NEW;
    END
    $function$
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_agent_runs_bind_owner
    ON omni_agent_runs
  `;
  await sql`
    CREATE TRIGGER omni_agent_runs_bind_owner
    BEFORE INSERT
    ON omni_agent_runs
    FOR EACH ROW
    EXECUTE FUNCTION omni_bind_agent_run_owner()
  `;
  await sql`
    ALTER TABLE omni_agent_runs
    ALTER COLUMN owner_actor_id SET NOT NULL
  `;
  await sql`
    DO $migration$
    BEGIN
      IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'omni_agent_runs'::regclass
          AND conname = 'omni_agent_runs_owner_actor_check'
      ) THEN
        ALTER TABLE omni_agent_runs
        ADD CONSTRAINT omni_agent_runs_owner_actor_check CHECK (
          owner_actor_id = btrim(owner_actor_id)
          AND char_length(owner_actor_id) BETWEEN 1 AND 320
        ) NOT VALID;
      END IF;
    END
    $migration$
  `;
  await sql`
    ALTER TABLE omni_agent_runs
    VALIDATE CONSTRAINT omni_agent_runs_owner_actor_check
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_agent_runs_actor_started_idx
    ON omni_agent_runs (tenant_id, owner_actor_id, started_at DESC)
  `;
  await sql`
    CREATE OR REPLACE FUNCTION omni_reject_agent_run_owner_change()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    AS $function$
    BEGIN
      IF ROW(OLD.tenant_id, OLD.owner_actor_id)
        IS DISTINCT FROM ROW(NEW.tenant_id, NEW.owner_actor_id)
      THEN
        RAISE EXCEPTION 'Agent run ownership is immutable'
          USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END
    $function$
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_agent_runs_owner_immutable
    ON omni_agent_runs
  `;
  await sql`
    CREATE TRIGGER omni_agent_runs_owner_immutable
    BEFORE UPDATE OF tenant_id, owner_actor_id
    ON omni_agent_runs
    FOR EACH ROW
    EXECUTE FUNCTION omni_reject_agent_run_owner_change()
  `;

  const policies = [
    [
      "omni_agent_runs",
      "omni_agent_runs_actor_scope",
      `omni_system_scope_enabled() OR public.omni_actor_scope_v1_allows_validated(
        (SELECT public.omni_current_actor_scope_v1()),
        tenant_id,
        owner_actor_id
      )`,
    ],
    [
      "omni_threads",
      "omni_threads_actor_scope",
      `omni_system_scope_enabled() OR public.omni_actor_scope_v1_allows_validated(
        (SELECT public.omni_current_actor_scope_v1()),
        tenant_id,
        actor_id
      )`,
    ],
    [
      "omni_agent_events",
      "omni_agent_events_actor_scope",
      `omni_system_scope_enabled() OR EXISTS (
        SELECT 1 FROM omni_agent_runs parent_run
        WHERE parent_run.tenant_id = omni_agent_events.tenant_id
          AND parent_run.id = omni_agent_events.run_id
      )`,
    ],
    [
      "omni_thread_turns",
      "omni_thread_turns_actor_scope",
      `omni_system_scope_enabled() OR EXISTS (
        SELECT 1 FROM omni_threads parent_thread
        WHERE parent_thread.tenant_id = omni_thread_turns.tenant_id
          AND parent_thread.id = omni_thread_turns.thread_id
      )`,
    ],
    [
      "omni_events",
      "omni_run_events_actor_scope",
      `omni_system_scope_enabled()
        OR left(stream_id, 4) <> 'run:'
        OR EXISTS (
          SELECT 1 FROM omni_agent_runs parent_run
          WHERE parent_run.tenant_id = omni_events.tenant_id
            AND parent_run.id = substr(omni_events.stream_id, 5)
        )`,
    ],
    [
      "omni_run_checkpoints",
      "omni_run_checkpoints_actor_scope",
      `omni_system_scope_enabled() OR public.omni_actor_scope_v1_allows_validated(
        (SELECT public.omni_current_actor_scope_v1()),
        tenant_id,
        actor_id
      )`,
    ],
    [
      "omni_run_checkpoint_state_references",
      "omni_run_checkpoint_references_actor_scope",
      `omni_system_scope_enabled() OR EXISTS (
        SELECT 1 FROM omni_run_checkpoints parent_checkpoint
        WHERE parent_checkpoint.tenant_id =
            omni_run_checkpoint_state_references.tenant_id
          AND parent_checkpoint.run_id =
            omni_run_checkpoint_state_references.run_id
          AND parent_checkpoint.checkpoint_id =
            omni_run_checkpoint_state_references.checkpoint_id
      )`,
    ],
    [
      "omni_run_checkpoint_resume_claims",
      "omni_run_checkpoint_resume_claims_actor_scope",
      `omni_system_scope_enabled() OR EXISTS (
        SELECT 1 FROM omni_run_checkpoints parent_checkpoint
        WHERE parent_checkpoint.tenant_id =
            omni_run_checkpoint_resume_claims.tenant_id
          AND parent_checkpoint.run_id =
            omni_run_checkpoint_resume_claims.run_id
          AND parent_checkpoint.checkpoint_id =
            omni_run_checkpoint_resume_claims.checkpoint_id
      )`,
    ],
    [
      "omni_run_forks",
      "omni_run_forks_actor_scope",
      `omni_system_scope_enabled() OR public.omni_actor_scope_v1_allows_validated(
        (SELECT public.omni_current_actor_scope_v1()),
        tenant_id,
        initiating_actor_id
      )`,
    ],
  ] as const;
  for (const [tableName, policyName, predicate] of policies) {
    await sql.query(`DROP POLICY IF EXISTS ${policyName} ON ${tableName}`);
    await sql.query(`
      CREATE POLICY ${policyName}
      ON ${tableName}
      AS RESTRICTIVE
      FOR ALL
      USING (${predicate})
      WITH CHECK (${predicate})
    `);
  }

  await sql`
    UPDATE omni_operation_jobs job
    SET payload = jsonb_set(
      job.payload,
      '{actorId}',
      to_jsonb(run.owner_actor_id),
      TRUE
    )
    FROM omni_agent_runs run
    WHERE job.type = 'agent.resume'
      AND NOT job.payload ? 'actorId'
      AND run.tenant_id = job.tenant_id
      AND run.id = job.payload ->> 'agentRunId'
  `;
  await sql`
    UPDATE omni_operation_jobs job
    SET payload = jsonb_set(
      job.payload,
      '{request,actorId}',
      to_jsonb(run.owner_actor_id),
      TRUE
    )
    FROM omni_agent_runs run
    WHERE job.type = 'memory.consolidate'
      AND NULLIF(btrim(job.payload #>> '{request,actorId}'), '') IS NULL
      AND run.tenant_id = job.tenant_id
      AND run.id = job.payload #>> '{request,runId}'
  `;

  await sql`
    DO $migration$
    DECLARE
      protected_table TEXT;
      protected_policy TEXT;
    BEGIN
      IF EXISTS (
        SELECT 1 FROM omni_agent_runs
        WHERE owner_actor_id IS NULL
          OR owner_actor_id IS DISTINCT FROM btrim(owner_actor_id)
          OR char_length(owner_actor_id) NOT BETWEEN 1 AND 320
      ) THEN
        RAISE EXCEPTION 'Agent run ownership backfill is incomplete'
          USING ERRCODE = '55000';
      END IF;
      FOR protected_table, protected_policy IN
        SELECT * FROM (VALUES
          ('omni_agent_runs', 'omni_agent_runs_actor_scope'),
          ('omni_threads', 'omni_threads_actor_scope'),
          ('omni_agent_events', 'omni_agent_events_actor_scope'),
          ('omni_thread_turns', 'omni_thread_turns_actor_scope'),
          ('omni_events', 'omni_run_events_actor_scope'),
          ('omni_run_checkpoints', 'omni_run_checkpoints_actor_scope'),
          (
            'omni_run_checkpoint_state_references',
            'omni_run_checkpoint_references_actor_scope'
          ),
          (
            'omni_run_checkpoint_resume_claims',
            'omni_run_checkpoint_resume_claims_actor_scope'
          ),
          ('omni_run_forks', 'omni_run_forks_actor_scope')
        ) expected(table_name, policy_name)
      LOOP
        IF NOT EXISTS (
          SELECT 1 FROM pg_class
          WHERE oid = protected_table::regclass
            AND relrowsecurity
            AND relforcerowsecurity
        ) OR NOT EXISTS (
          SELECT 1 FROM pg_policy
          WHERE polrelid = protected_table::regclass
            AND polname = protected_policy
            AND NOT polpermissive
            AND polcmd = '*'
        ) THEN
          RAISE EXCEPTION 'Actor-private policy is missing for %', protected_table
            USING ERRCODE = '55000';
        END IF;
      END LOOP;
    END
    $migration$
  `;
}

async function ensureActorPrivateToolExecutionLedgers(sql: SqlClient) {
  await sql`
    UPDATE omni_tool_executions execution_record
    SET tenant_id = 'default'
    WHERE tenant_id IS NULL OR btrim(tenant_id) = ''
  `;
  await sql`
    UPDATE omni_tool_executions execution_record
    SET actor_id = COALESCE(
      NULLIF(btrim(execution_record.actor_id), ''),
      (
        SELECT NULLIF(
          btrim(event.payload #>> '{_executionScope,initiatingActorId}'),
          ''
        )
        FROM omni_events event
        WHERE event.tenant_id = execution_record.tenant_id
          AND event.stream_id = 'tool_execution:' || execution_record.id
          AND event.payload ? '_executionScope'
        ORDER BY
          CASE WHEN event.type = 'tool.scope_bound' THEN 0 ELSE 1 END,
          event.seq ASC
        LIMIT 1
      ),
      NULLIF(btrim(execution_record.effect_receipt ->> 'actorId'), ''),
      (
        SELECT run.owner_actor_id
        FROM omni_agent_runs run
        WHERE run.tenant_id = execution_record.tenant_id
          AND run.continuation #>> '{pendingToolCall,executionId}' =
            execution_record.id
        ORDER BY run.started_at DESC, run.id ASC
        LIMIT 1
      ),
      'quarantine:tool:' || left(execution_record.id, 299)
    )
    WHERE execution_record.actor_id IS NULL
      OR btrim(execution_record.actor_id) = ''
  `;
  await sql`
    ALTER TABLE omni_tool_executions
    ALTER COLUMN tenant_id SET DEFAULT 'default'
  `;
  await sql`
    ALTER TABLE omni_tool_executions
    ALTER COLUMN tenant_id SET NOT NULL
  `;
  await sql`
    ALTER TABLE omni_tool_executions
    ALTER COLUMN actor_id SET NOT NULL
  `;
  await sql`
    DO $migration$
    BEGIN
      IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'omni_tool_executions'::regclass
          AND conname = 'omni_tool_executions_actor_check'
      ) THEN
        ALTER TABLE omni_tool_executions
        ADD CONSTRAINT omni_tool_executions_actor_check CHECK (
          actor_id = btrim(actor_id)
          AND char_length(actor_id) BETWEEN 1 AND 320
        ) NOT VALID;
      END IF;
    END
    $migration$
  `;
  await sql`
    ALTER TABLE omni_tool_executions
    VALIDATE CONSTRAINT omni_tool_executions_actor_check
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_tool_executions_actor_created_idx
    ON omni_tool_executions (tenant_id, actor_id, created_at DESC)
  `;

  await sql`
    CREATE OR REPLACE FUNCTION omni_bind_tool_execution_actor()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = pg_catalog, public
    AS $function$
    DECLARE
      actor_scope JSONB;
    BEGIN
      IF NEW.tenant_id IS NULL OR btrim(NEW.tenant_id) = '' THEN
        NEW.tenant_id := NULLIF(
          current_setting('omni.tenant_id', TRUE),
          ''
        );
      END IF;
      IF NEW.actor_id IS NULL OR btrim(NEW.actor_id) = '' THEN
        actor_scope := public.omni_current_actor_scope_v1();
        IF actor_scope IS NOT NULL THEN
          NEW.actor_id := actor_scope -> 'actorIds' ->>
            (jsonb_array_length(actor_scope -> 'actorIds') - 1);
        END IF;
      END IF;
      IF NEW.tenant_id IS NULL OR NEW.actor_id IS NULL THEN
        RAISE EXCEPTION
          'Governed tool execution requires an actor-bound database scope'
          USING ERRCODE = '42501';
      END IF;
      RETURN NEW;
    END
    $function$
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_tool_executions_bind_actor
    ON omni_tool_executions
  `;
  await sql`
    CREATE TRIGGER omni_tool_executions_bind_actor
    BEFORE INSERT
    ON omni_tool_executions
    FOR EACH ROW
    EXECUTE FUNCTION omni_bind_tool_execution_actor()
  `;

  await sql`
    CREATE OR REPLACE FUNCTION omni_reject_tool_execution_identity_change()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = pg_catalog, public
    AS $function$
    BEGIN
      IF ROW(
        OLD.id,
        OLD.tenant_id,
        OLD.actor_id,
        OLD.tool_id,
        OLD.tool_name,
        OLD.risk_level,
        OLD.dry_run,
        OLD.approval_required,
        OLD.input,
        OLD.created_at
      ) IS DISTINCT FROM ROW(
        NEW.id,
        NEW.tenant_id,
        NEW.actor_id,
        NEW.tool_id,
        NEW.tool_name,
        NEW.risk_level,
        NEW.dry_run,
        NEW.approval_required,
        NEW.input,
        NEW.created_at
      ) THEN
        RAISE EXCEPTION 'Governed tool execution identity is immutable'
          USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END
    $function$
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_tool_executions_identity_immutable
    ON omni_tool_executions
  `;
  await sql`
    CREATE TRIGGER omni_tool_executions_identity_immutable
    BEFORE UPDATE OF
      id,
      tenant_id,
      actor_id,
      tool_id,
      tool_name,
      risk_level,
      dry_run,
      approval_required,
      input,
      created_at
    ON omni_tool_executions
    FOR EACH ROW
    EXECUTE FUNCTION omni_reject_tool_execution_identity_change()
  `;

  await sql`
    CREATE OR REPLACE FUNCTION omni_actor_scope_v1_is_active_admin(
      actor_scope JSONB,
      row_tenant_id TEXT
    )
    RETURNS BOOLEAN
    LANGUAGE SQL
    STABLE
    SECURITY INVOKER
    SET search_path = pg_catalog, public
    AS $function$
      SELECT COALESCE(
        actor_scope ->> 'tenantId' = row_tenant_id
        AND EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            actor_scope -> 'actorIds'
          ) scoped_actor(actor_id)
          JOIN public.omni_auth_users auth_user
            ON auth_user.actor_id COLLATE "C" =
                scoped_actor.actor_id COLLATE "C"
              OR auth_user.email COLLATE "C" =
                scoped_actor.actor_id COLLATE "C"
          JOIN public.omni_auth_memberships membership
            ON membership.tenant_id = row_tenant_id
            AND membership.user_id = auth_user.id
          WHERE auth_user.status = 'active'
            AND membership.status = 'active'
            AND membership.role IN ('admin', 'system')
        ),
        FALSE
      )
    $function$
  `;
  await sql`
    CREATE OR REPLACE FUNCTION omni_tool_execution_actor_access_v1(
      actor_scope JSONB,
      row_tenant_id TEXT,
      owner_actor_id TEXT,
      row_risk_level INTEGER,
      row_status TEXT,
      row_approvals JSONB,
      row_approved_by TEXT
    )
    RETURNS BOOLEAN
    LANGUAGE SQL
    STABLE
    SECURITY INVOKER
    SET search_path = pg_catalog, public
    AS $function$
      SELECT COALESCE(
        public.omni_actor_scope_v1_allows_validated(
          actor_scope,
          row_tenant_id,
          owner_actor_id
        )
        OR (
          row_risk_level >= 3
          AND public.omni_actor_scope_v1_is_active_admin(
            actor_scope,
            row_tenant_id
          )
          AND (
            row_status = 'approval_required'
            OR EXISTS (
              SELECT 1
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(row_approvals) = 'array'
                  THEN row_approvals
                  ELSE '[]'::JSONB
                END
              ) approval
              JOIN jsonb_array_elements_text(
                actor_scope -> 'actorIds'
              ) scoped_actor(actor_id)
                ON (approval ->> 'by') COLLATE "C" =
                  scoped_actor.actor_id COLLATE "C"
              WHERE approval ->> 'role' IN ('admin', 'system')
            )
            OR EXISTS (
              SELECT 1
              FROM jsonb_array_elements_text(
                actor_scope -> 'actorIds'
              ) scoped_actor(actor_id)
              WHERE row_approved_by COLLATE "C" =
                scoped_actor.actor_id COLLATE "C"
            )
          )
        ),
        FALSE
      )
    $function$
  `;

  const toolExecutionPredicate = `
    omni_system_scope_enabled()
    OR public.omni_tool_execution_actor_access_v1(
      (SELECT public.omni_current_actor_scope_v1()),
      tenant_id,
      actor_id,
      risk_level,
      status,
      approvals,
      approved_by
    )
  `;
  await sql.query(`
    DROP POLICY IF EXISTS omni_tool_executions_actor_scope
    ON omni_tool_executions
  `);
  await sql.query(`
    CREATE POLICY omni_tool_executions_actor_scope
    ON omni_tool_executions
    AS RESTRICTIVE
    FOR ALL
    USING (${toolExecutionPredicate})
    WITH CHECK (${toolExecutionPredicate})
  `);

  const toolEventPredicate = `
    omni_system_scope_enabled()
    OR left(stream_id, 15) <> 'tool_execution:'
    OR public.omni_actor_scope_v1_allows_validated(
      (SELECT public.omni_current_actor_scope_v1()),
      tenant_id,
      actor_id
    )
    OR EXISTS (
      SELECT 1
      FROM omni_tool_executions parent_execution
      WHERE parent_execution.tenant_id = omni_events.tenant_id
        AND parent_execution.id = substr(omni_events.stream_id, 16)
    )
  `;
  await sql.query(`
    DROP POLICY IF EXISTS omni_tool_events_actor_scope
    ON omni_events
  `);
  await sql.query(`
    CREATE POLICY omni_tool_events_actor_scope
    ON omni_events
    AS RESTRICTIVE
    FOR ALL
    USING (${toolEventPredicate})
    WITH CHECK (${toolEventPredicate})
  `);

  await sql`
    DO $migration$
    BEGIN
      IF EXISTS (
        SELECT 1 FROM omni_tool_executions
        WHERE tenant_id IS NULL
          OR actor_id IS NULL
          OR actor_id IS DISTINCT FROM btrim(actor_id)
          OR char_length(actor_id) NOT BETWEEN 1 AND 320
      ) THEN
        RAISE EXCEPTION 'Governed tool execution ownership backfill is incomplete'
          USING ERRCODE = '55000';
      END IF;
      IF NOT EXISTS (
        SELECT 1 FROM pg_class
        WHERE oid = 'omni_tool_executions'::regclass
          AND relrowsecurity
          AND relforcerowsecurity
      ) OR NOT EXISTS (
        SELECT 1 FROM pg_policy
        WHERE polrelid = 'omni_tool_executions'::regclass
          AND polname = 'omni_tool_executions_actor_scope'
          AND NOT polpermissive
          AND polcmd = '*'
      ) OR NOT EXISTS (
        SELECT 1 FROM pg_policy
        WHERE polrelid = 'omni_events'::regclass
          AND polname = 'omni_tool_events_actor_scope'
          AND NOT polpermissive
          AND polcmd = '*'
      ) THEN
        RAISE EXCEPTION 'Actor-private governed tool policy is incomplete'
          USING ERRCODE = '55000';
      END IF;
    END
    $migration$
  `;
}

async function ensureToolExecutionRetentionRedactionV1(sql: SqlClient) {
  await sql`
    CREATE OR REPLACE FUNCTION omni_reject_tool_execution_identity_change()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
    SET search_path = pg_catalog, public
    AS $function$
    DECLARE
      is_expired_approval_redaction BOOLEAN;
    BEGIN
      is_expired_approval_redaction :=
        OLD.input IS DISTINCT FROM NEW.input
        AND OLD.status = 'approval_required'
        AND OLD.output IS NULL
        AND OLD.approval_decision IS NULL
        AND OLD.effect_receipt IS NULL
        AND OLD.completed_at IS NULL
        AND NEW.status = 'rejected'
        AND NEW.input = '{"redacted":"expired approval"}'::JSONB
        AND NEW.output IS NULL
        AND NEW.reason = 'Approval expired before an operator decision.'
        AND NEW.approval_decision = 'rejected'
        AND NEW.approval_reason = 'Expired by retention policy.'
        AND NEW.effect_receipt IS NULL
        AND NEW.completed_at IS NOT NULL;

      IF ROW(
        OLD.id,
        OLD.tenant_id,
        OLD.actor_id,
        OLD.tool_id,
        OLD.tool_name,
        OLD.risk_level,
        OLD.dry_run,
        OLD.approval_required,
        OLD.created_at
      ) IS DISTINCT FROM ROW(
        NEW.id,
        NEW.tenant_id,
        NEW.actor_id,
        NEW.tool_id,
        NEW.tool_name,
        NEW.risk_level,
        NEW.dry_run,
        NEW.approval_required,
        NEW.created_at
      ) OR (
        OLD.input IS DISTINCT FROM NEW.input
        AND NOT is_expired_approval_redaction
      ) THEN
        RAISE EXCEPTION 'Governed tool execution identity is immutable'
          USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END
    $function$
  `;
}

async function ensureEvidenceBasedMemoryFormation(sql: SqlClient) {
  await sql`DROP TABLE IF EXISTS pg_temp.omni_response_memory_quarantine`;
  await sql`
    CREATE TEMP TABLE omni_response_memory_quarantine
    ON COMMIT DROP
    AS
    SELECT tenant_id, id
    FROM omni_memories
    WHERE claim_status = 'active'
      AND (
        (
          source IN ('agent', 'consolidator')
          AND asserted_by = 'agent'
        )
        OR (
          source = 'workflow'
          AND type = 'episode'
        )
      )
  `;
  await sql`
    INSERT INTO omni_events (
      id, stream_id, type, tenant_id, actor_id, payload,
      causation_id, correlation_id, at
    )
    SELECT
      'memory_response_quarantine_' || md5(
        quarantine.tenant_id || ':' || quarantine.id
      ),
      'memory:' || quarantine.id,
      'memory.response_derived.quarantined',
      quarantine.tenant_id,
      'system',
      jsonb_build_object(
        'schemaVersion', 1,
        'memoryId', quarantine.id,
        'previousClaimStatus', 'active',
        'claimStatus', 'candidate',
        'reasonCode', 'unsupported_response_derived_claim'
      ),
      quarantine.id,
      'schema-migration:83',
      NOW()
    FROM omni_response_memory_quarantine quarantine
    ON CONFLICT (id) DO NOTHING
  `;
  await sql`
    UPDATE omni_memories memory
    SET claim_status = 'candidate',
        updated_at = NOW()
    FROM omni_response_memory_quarantine quarantine
    WHERE memory.tenant_id = quarantine.tenant_id
      AND memory.id = quarantine.id
  `;
  await sql`
    DELETE FROM omni_memory_graph_edges edge
    WHERE EXISTS (
      SELECT 1
      FROM omni_response_memory_quarantine quarantine
      WHERE quarantine.tenant_id = edge.tenant_id
        AND quarantine.id = ANY(edge.memory_ids)
    )
    OR EXISTS (
      SELECT 1
      FROM omni_memory_graph_nodes endpoint
      JOIN omni_response_memory_quarantine quarantine
        ON quarantine.tenant_id = endpoint.tenant_id
       AND quarantine.id = ANY(endpoint.memory_ids)
      WHERE endpoint.tenant_id = edge.tenant_id
        AND endpoint.id IN (edge.source_node_id, edge.target_node_id)
    )
  `;
  await sql`
    DELETE FROM omni_memory_graph_nodes node
    WHERE EXISTS (
      SELECT 1
      FROM omni_response_memory_quarantine quarantine
      WHERE quarantine.tenant_id = node.tenant_id
        AND quarantine.id = ANY(node.memory_ids)
    )
  `;
  await sql`
    DELETE FROM omni_daily_briefs brief
    WHERE EXISTS (
      SELECT 1
      FROM omni_response_memory_quarantine quarantine
      WHERE quarantine.tenant_id = brief.tenant_id
        AND quarantine.id = ANY(brief.memory_ids)
    )
  `;
  await sql`
    INSERT INTO omni_memory_graph_rebuild_queue AS rebuild (
      tenant_id, requested_at, attempts, last_error, updated_at, generation
    )
    SELECT DISTINCT
      quarantine.tenant_id, NOW(), 0, NULL, NOW(), 1
    FROM omni_response_memory_quarantine quarantine
    ON CONFLICT (tenant_id) DO UPDATE SET
      requested_at = NOW(),
      attempts = 0,
      last_error = NULL,
      updated_at = NOW(),
      generation = rebuild.generation + 1
  `;
}

async function ensureEntityRegistryV1(sql: SqlClient) {
  await sql`
    CREATE TABLE IF NOT EXISTS omni_entity_records (
      tenant_id TEXT NOT NULL,
      id TEXT NOT NULL,
      owner_actor_id TEXT NOT NULL,
      ontology_version_id TEXT NOT NULL,
      entity_type_id TEXT NOT NULL,
      canonical_label TEXT NOT NULL,
      normalized_label_sha256 TEXT NOT NULL,
      state TEXT NOT NULL,
      merged_into_entity_id TEXT,
      access_scope_sha256 TEXT NOT NULL,
      contract JSONB NOT NULL,
      entity_sha256 TEXT NOT NULL,
      created_at TIMESTAMPTZ NOT NULL,
      updated_at TIMESTAMPTZ NOT NULL,
      PRIMARY KEY (tenant_id, id),
      FOREIGN KEY (tenant_id, merged_into_entity_id)
        REFERENCES omni_entity_records(tenant_id, id),
      CHECK (char_length(owner_actor_id) BETWEEN 1 AND 320),
      CHECK (ontology_version_id = 'asael-ontology:1'),
      CHECK (entity_type_id IN (
        'person', 'organization', 'account', 'project', 'work_item',
        'event', 'meeting', 'place', 'asset', 'decision', 'commitment',
        'preference', 'risk', 'goal', 'product', 'case', 'opportunity'
      )),
      CHECK (state IN ('active', 'merged', 'retired')),
      CHECK ((state = 'merged') = (merged_into_entity_id IS NOT NULL)),
      CHECK (normalized_label_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (access_scope_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (entity_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (contract ->> 'entityId' = id),
      CHECK (contract ->> 'ontologyVersionId' = ontology_version_id),
      CHECK (contract ->> 'entityTypeId' = entity_type_id),
      CHECK (contract ->> 'state' = state),
      CHECK (contract ->> 'entitySha256' = entity_sha256),
      CHECK (contract #>> '{accessBinding,tenantId}' = tenant_id),
      CHECK (contract #>> '{accessBinding,ownerActorId}' = owner_actor_id),
      CHECK (
        contract #>> '{accessBinding,accessScopeSha256}' = access_scope_sha256
      )
    )
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_entity_records_resolution_idx
    ON omni_entity_records (
      tenant_id, owner_actor_id, entity_type_id, access_scope_sha256,
      normalized_label_sha256
    )
    WHERE state = 'active'
  `;
  await sql`
    CREATE TABLE IF NOT EXISTS omni_entity_aliases (
      tenant_id TEXT NOT NULL,
      id TEXT NOT NULL,
      owner_actor_id TEXT NOT NULL,
      entity_id TEXT NOT NULL,
      normalized_alias_sha256 TEXT NOT NULL,
      access_scope_sha256 TEXT NOT NULL,
      state TEXT NOT NULL,
      contract JSONB NOT NULL,
      alias_sha256 TEXT NOT NULL,
      created_at TIMESTAMPTZ NOT NULL,
      PRIMARY KEY (tenant_id, id),
      FOREIGN KEY (tenant_id, entity_id)
        REFERENCES omni_entity_records(tenant_id, id),
      CHECK (char_length(owner_actor_id) BETWEEN 1 AND 320),
      CHECK (state IN ('active', 'retired')),
      CHECK (normalized_alias_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (access_scope_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (alias_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (contract ->> 'aliasId' = id),
      CHECK (contract ->> 'entityId' = entity_id),
      CHECK (contract ->> 'state' = state),
      CHECK (contract ->> 'accessScopeSha256' = access_scope_sha256),
      CHECK (contract ->> 'aliasSha256' = alias_sha256)
    )
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_entity_aliases_resolution_idx
    ON omni_entity_aliases (
      tenant_id, owner_actor_id, access_scope_sha256,
      normalized_alias_sha256
    )
    WHERE state = 'active'
  `;
  await sql`
    CREATE TABLE IF NOT EXISTS omni_entity_resolutions (
      tenant_id TEXT NOT NULL,
      id TEXT NOT NULL,
      owner_actor_id TEXT NOT NULL,
      entity_type_id TEXT NOT NULL,
      access_scope_sha256 TEXT NOT NULL,
      decision TEXT NOT NULL,
      selected_entity_id TEXT,
      contract JSONB NOT NULL,
      decision_sha256 TEXT NOT NULL,
      decided_at TIMESTAMPTZ NOT NULL,
      PRIMARY KEY (tenant_id, id),
      FOREIGN KEY (tenant_id, selected_entity_id)
        REFERENCES omni_entity_records(tenant_id, id),
      CHECK (char_length(owner_actor_id) BETWEEN 1 AND 320),
      CHECK (decision IN ('auto_link', 'review_required', 'create_new')),
      CHECK ((decision = 'auto_link') = (selected_entity_id IS NOT NULL)),
      CHECK (access_scope_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (decision_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (contract ->> 'resolutionId' = id),
      CHECK (contract ->> 'tenantId' = tenant_id),
      CHECK (contract ->> 'ownerActorId' = owner_actor_id),
      CHECK (contract ->> 'entityTypeId' = entity_type_id),
      CHECK (contract ->> 'decision' = decision),
      CHECK (contract ->> 'accessScopeSha256' = access_scope_sha256),
      CHECK (contract ->> 'decisionSha256' = decision_sha256)
    )
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_entity_resolutions_actor_at_idx
    ON omni_entity_resolutions (tenant_id, owner_actor_id, decided_at DESC)
  `;
  await sql`
    CREATE TABLE IF NOT EXISTS omni_entity_merge_reviews (
      tenant_id TEXT NOT NULL,
      id TEXT NOT NULL,
      owner_actor_id TEXT NOT NULL,
      resolution_id TEXT NOT NULL,
      source_entity_id TEXT NOT NULL,
      target_entity_id TEXT NOT NULL,
      access_scope_sha256 TEXT NOT NULL,
      decision TEXT NOT NULL,
      previous_review_id TEXT,
      reviewer_actor_id TEXT NOT NULL,
      contract JSONB NOT NULL,
      review_sha256 TEXT NOT NULL,
      reviewed_at TIMESTAMPTZ NOT NULL,
      PRIMARY KEY (tenant_id, id),
      FOREIGN KEY (tenant_id, resolution_id)
        REFERENCES omni_entity_resolutions(tenant_id, id),
      FOREIGN KEY (tenant_id, source_entity_id)
        REFERENCES omni_entity_records(tenant_id, id),
      FOREIGN KEY (tenant_id, target_entity_id)
        REFERENCES omni_entity_records(tenant_id, id),
      FOREIGN KEY (tenant_id, previous_review_id)
        REFERENCES omni_entity_merge_reviews(tenant_id, id),
      CHECK (char_length(owner_actor_id) BETWEEN 1 AND 320),
      CHECK (reviewer_actor_id = owner_actor_id),
      CHECK (decision IN ('approved', 'rejected', 'reversed')),
      CHECK ((decision = 'reversed') = (previous_review_id IS NOT NULL)),
      CHECK (access_scope_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (review_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK (contract ->> 'reviewId' = id),
      CHECK (contract ->> 'resolutionId' = resolution_id),
      CHECK (contract ->> 'tenantId' = tenant_id),
      CHECK (contract ->> 'ownerActorId' = owner_actor_id),
      CHECK (contract ->> 'decision' = decision),
      CHECK (contract ->> 'accessScopeSha256' = access_scope_sha256),
      CHECK (contract ->> 'reviewSha256' = review_sha256)
    )
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_entity_merge_reviews_actor_at_idx
    ON omni_entity_merge_reviews (tenant_id, owner_actor_id, reviewed_at DESC)
  `;
  await sql`
    CREATE UNIQUE INDEX IF NOT EXISTS omni_entity_merge_reviews_one_reversal_idx
    ON omni_entity_merge_reviews (tenant_id, previous_review_id)
    WHERE decision = 'reversed'
  `;
  await sql`
    CREATE OR REPLACE FUNCTION omni_reject_entity_registry_identity_change()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    AS $function$
    BEGIN
      IF TG_TABLE_NAME = 'omni_entity_records' AND ROW(
        OLD.tenant_id, OLD.id, OLD.owner_actor_id, OLD.ontology_version_id,
        OLD.entity_type_id, OLD.canonical_label, OLD.normalized_label_sha256,
        OLD.access_scope_sha256, OLD.created_at
      ) IS DISTINCT FROM ROW(
        NEW.tenant_id, NEW.id, NEW.owner_actor_id, NEW.ontology_version_id,
        NEW.entity_type_id, NEW.canonical_label, NEW.normalized_label_sha256,
        NEW.access_scope_sha256, NEW.created_at
      ) THEN
        RAISE EXCEPTION 'Entity identity and access scope are immutable'
          USING ERRCODE = '55000';
      END IF;
      IF TG_TABLE_NAME = 'omni_entity_aliases' AND ROW(
        OLD.tenant_id, OLD.id, OLD.owner_actor_id, OLD.entity_id,
        OLD.normalized_alias_sha256, OLD.access_scope_sha256, OLD.created_at
      ) IS DISTINCT FROM ROW(
        NEW.tenant_id, NEW.id, NEW.owner_actor_id, NEW.entity_id,
        NEW.normalized_alias_sha256, NEW.access_scope_sha256, NEW.created_at
      ) THEN
        RAISE EXCEPTION 'Entity alias identity and access scope are immutable'
          USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END
    $function$
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_entity_records_identity_immutable
    ON omni_entity_records
  `;
  await sql`
    CREATE TRIGGER omni_entity_records_identity_immutable
    BEFORE UPDATE ON omni_entity_records
    FOR EACH ROW EXECUTE FUNCTION omni_reject_entity_registry_identity_change()
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_entity_aliases_identity_immutable
    ON omni_entity_aliases
  `;
  await sql`
    CREATE TRIGGER omni_entity_aliases_identity_immutable
    BEFORE UPDATE ON omni_entity_aliases
    FOR EACH ROW EXECUTE FUNCTION omni_reject_entity_registry_identity_change()
  `;
  await ensureTenantIsolationPolicies(sql);
  await sql`
    DO $migration$
    DECLARE
      relation_name TEXT;
      policy_name TEXT;
    BEGIN
      FOREACH relation_name IN ARRAY ARRAY[
        'omni_entity_records',
        'omni_entity_aliases',
        'omni_entity_resolutions',
        'omni_entity_merge_reviews'
      ] LOOP
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', relation_name);
        EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', relation_name);
        policy_name := relation_name || '_actor_select';
        EXECUTE format('DROP POLICY IF EXISTS %I ON %I', policy_name, relation_name);
        EXECUTE format(
          'CREATE POLICY %I ON %I AS RESTRICTIVE FOR SELECT USING '
          || '(omni_system_scope_enabled() OR '
          || 'omni_actor_scope_v1_allows(tenant_id, owner_actor_id))',
          policy_name,
          relation_name
        );
        policy_name := relation_name || '_actor_insert';
        EXECUTE format('DROP POLICY IF EXISTS %I ON %I', policy_name, relation_name);
        EXECUTE format(
          'CREATE POLICY %I ON %I AS RESTRICTIVE FOR INSERT WITH CHECK '
          || '(omni_system_scope_enabled() OR '
          || 'omni_actor_scope_v1_allows(tenant_id, owner_actor_id))',
          policy_name,
          relation_name
        );
      END LOOP;
      FOREACH relation_name IN ARRAY ARRAY[
        'omni_entity_records',
        'omni_entity_aliases'
      ] LOOP
        policy_name := relation_name || '_actor_update';
        EXECUTE format('DROP POLICY IF EXISTS %I ON %I', policy_name, relation_name);
        EXECUTE format(
          'CREATE POLICY %I ON %I AS RESTRICTIVE FOR UPDATE USING '
          || '(omni_system_scope_enabled() OR '
          || 'omni_actor_scope_v1_allows(tenant_id, owner_actor_id)) '
          || 'WITH CHECK (omni_system_scope_enabled() OR '
          || 'omni_actor_scope_v1_allows(tenant_id, owner_actor_id))',
          policy_name,
          relation_name
        );
      END LOOP;
    END
    $migration$
  `;
  await sql`
    DO $migration$
    BEGIN
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'omni_runtime') THEN
        GRANT SELECT, INSERT, UPDATE ON
          omni_entity_records,
          omni_entity_aliases
        TO omni_runtime;
        GRANT SELECT, INSERT ON
          omni_entity_resolutions,
          omni_entity_merge_reviews
        TO omni_runtime;
      END IF;
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'omni_maintenance') THEN
        GRANT SELECT, INSERT, UPDATE ON
          omni_entity_records,
          omni_entity_aliases
        TO omni_maintenance;
        GRANT SELECT, INSERT ON
          omni_entity_resolutions,
          omni_entity_merge_reviews
        TO omni_maintenance;
      END IF;
    END
    $migration$
  `;
}

async function ensureEntityMemoryDeletionBarrier(sql: SqlClient) {
  await sql`
    ALTER TABLE omni_entity_records
    ADD COLUMN IF NOT EXISTS lineage_memory_ids TEXT[] NOT NULL DEFAULT '{}'
  `;
  await sql`
    ALTER TABLE omni_entity_aliases
    ADD COLUMN IF NOT EXISTS lineage_memory_ids TEXT[] NOT NULL DEFAULT '{}'
  `;
  await sql`
    UPDATE omni_entity_records record
    SET lineage_memory_ids = COALESCE((
      SELECT array_agg(reference ->> 'referenceId' ORDER BY reference ->> 'referenceId')
      FROM jsonb_array_elements(record.contract -> 'lineage') reference
      WHERE reference ->> 'kind' = 'memory'
    ), '{}'::TEXT[])
  `;
  await sql`
    UPDATE omni_entity_aliases alias
    SET lineage_memory_ids = CASE
      WHEN alias.contract #>> '{lineage,kind}' = 'memory'
      THEN ARRAY[alias.contract #>> '{lineage,referenceId}']
      ELSE '{}'::TEXT[]
    END
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_entity_records_memory_lineage_idx
    ON omni_entity_records USING GIN (lineage_memory_ids)
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_entity_aliases_memory_lineage_idx
    ON omni_entity_aliases USING GIN (lineage_memory_ids)
  `;

  await sql`
    CREATE OR REPLACE FUNCTION omni_reject_entity_deleted_memory_lineage()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    AS $function$
    BEGIN
      IF omni_memory_ids_have_deletion_barrier(
        NEW.tenant_id,
        NEW.lineage_memory_ids
      ) THEN
        RAISE EXCEPTION 'Entity lineage references permanently forgotten memory'
          USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END
    $function$
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_entity_records_memory_deletion_barrier
    ON omni_entity_records
  `;
  await sql`
    CREATE TRIGGER omni_entity_records_memory_deletion_barrier
    BEFORE INSERT OR UPDATE OF lineage_memory_ids ON omni_entity_records
    FOR EACH ROW EXECUTE FUNCTION omni_reject_entity_deleted_memory_lineage()
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_entity_aliases_memory_deletion_barrier
    ON omni_entity_aliases
  `;
  await sql`
    CREATE TRIGGER omni_entity_aliases_memory_deletion_barrier
    BEFORE INSERT OR UPDATE OF lineage_memory_ids ON omni_entity_aliases
    FOR EACH ROW EXECUTE FUNCTION omni_reject_entity_deleted_memory_lineage()
  `;

  await sql`
    CREATE OR REPLACE FUNCTION omni_reject_entity_registry_identity_change()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    AS $function$
    BEGIN
      IF TG_TABLE_NAME = 'omni_entity_records' THEN
        IF ROW(
          OLD.tenant_id, OLD.id, OLD.owner_actor_id, OLD.ontology_version_id,
          OLD.entity_type_id, OLD.normalized_label_sha256,
          OLD.access_scope_sha256, OLD.created_at
        ) IS DISTINCT FROM ROW(
          NEW.tenant_id, NEW.id, NEW.owner_actor_id, NEW.ontology_version_id,
          NEW.entity_type_id, NEW.normalized_label_sha256,
          NEW.access_scope_sha256, NEW.created_at
        ) THEN
          RAISE EXCEPTION 'Entity identity and access scope are immutable'
            USING ERRCODE = '55000';
        END IF;
        IF OLD.canonical_label IS DISTINCT FROM NEW.canonical_label
          AND NOT (
            OLD.state <> 'retired'
            AND NEW.state = 'retired'
            AND NEW.canonical_label = '[forgotten]'
          )
        THEN
          RAISE EXCEPTION 'Entity labels may only be scrubbed on retirement'
            USING ERRCODE = '55000';
        END IF;
      END IF;
      IF TG_TABLE_NAME = 'omni_entity_aliases' AND ROW(
        OLD.tenant_id, OLD.id, OLD.owner_actor_id, OLD.entity_id,
        OLD.normalized_alias_sha256, OLD.access_scope_sha256, OLD.created_at
      ) IS DISTINCT FROM ROW(
        NEW.tenant_id, NEW.id, NEW.owner_actor_id, NEW.entity_id,
        NEW.normalized_alias_sha256, NEW.access_scope_sha256, NEW.created_at
      ) THEN
        RAISE EXCEPTION 'Entity alias identity and access scope are immutable'
          USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END
    $function$
  `;

  await sql`
    DROP POLICY IF EXISTS omni_entity_memory_deletion_barrier
    ON omni_entity_records
  `;
  await sql`
    CREATE POLICY omni_entity_memory_deletion_barrier
    ON omni_entity_records
    AS RESTRICTIVE
    FOR SELECT
    USING (
      NOT omni_memory_ids_have_deletion_barrier(
        tenant_id,
        lineage_memory_ids
      )
    )
  `;
  await sql`
    DROP POLICY IF EXISTS omni_entity_memory_deletion_barrier
    ON omni_entity_aliases
  `;
  await sql`
    CREATE POLICY omni_entity_memory_deletion_barrier
    ON omni_entity_aliases
    AS RESTRICTIVE
    FOR SELECT
    USING (
      NOT omni_memory_ids_have_deletion_barrier(
        tenant_id,
        lineage_memory_ids
      )
    )
  `;

  await sql`
    DO $migration$
    BEGIN
      IF EXISTS (
        SELECT 1
        FROM omni_entity_records record
        WHERE record.lineage_memory_ids IS DISTINCT FROM COALESCE((
          SELECT array_agg(reference ->> 'referenceId' ORDER BY reference ->> 'referenceId')
          FROM jsonb_array_elements(record.contract -> 'lineage') reference
          WHERE reference ->> 'kind' = 'memory'
        ), '{}'::TEXT[])
      ) OR EXISTS (
        SELECT 1
        FROM omni_entity_aliases alias
        WHERE alias.lineage_memory_ids IS DISTINCT FROM CASE
          WHEN alias.contract #>> '{lineage,kind}' = 'memory'
          THEN ARRAY[alias.contract #>> '{lineage,referenceId}']
          ELSE '{}'::TEXT[]
        END
      ) OR (
        SELECT count(*)
        FROM pg_policy
        WHERE polname = 'omni_entity_memory_deletion_barrier'
          AND polrelid IN (
            'omni_entity_records'::regclass,
            'omni_entity_aliases'::regclass
          )
          AND NOT polpermissive
          AND polcmd = 'r'
      ) <> 2 OR (
        SELECT count(*)
        FROM pg_trigger
        WHERE tgname IN (
          'omni_entity_records_memory_deletion_barrier',
          'omni_entity_aliases_memory_deletion_barrier'
        )
          AND NOT tgisinternal
      ) <> 2 THEN
        RAISE EXCEPTION 'Entity memory deletion barrier is invalid'
          USING ERRCODE = '55000';
      END IF;
    END
    $migration$
  `;
}

async function ensureEntityMemoryLineageOwnerProbe(sql: SqlClient) {
  await sql`
    CREATE OR REPLACE FUNCTION omni_active_memory_lineage_owned_by(
      row_tenant_id TEXT,
      row_owner_actor_id TEXT,
      row_memory_ids TEXT[]
    )
    RETURNS BOOLEAN
    LANGUAGE SQL
    STABLE
    SECURITY DEFINER
    SET search_path = pg_catalog, public
    AS $function$
      SELECT COALESCE(
        public.omni_current_tenant() = row_tenant_id
        AND public.omni_actor_scope_v1_allows(
          row_tenant_id,
          row_owner_actor_id
        )
        AND cardinality(row_memory_ids) BETWEEN 1 AND 64
        AND cardinality(ARRAY(
          SELECT DISTINCT memory_id COLLATE "C"
          FROM unnest(row_memory_ids) memory_id
          ORDER BY memory_id COLLATE "C"
        )) = cardinality(row_memory_ids)
        AND NOT public.omni_memory_ids_have_deletion_barrier(
          row_tenant_id,
          row_memory_ids
        )
        AND (
          SELECT count(*)
          FROM public.omni_memories memory
          WHERE memory.tenant_id = row_tenant_id
            AND memory.owner_actor_id = row_owner_actor_id
            AND memory.id = ANY(row_memory_ids)
            AND memory.access_contract_version = 1
            AND memory.access_state = 'scope_bound'
            AND memory.visibility = 'user_private'
            AND memory.claim_status = 'active'
        ) = cardinality(row_memory_ids),
        FALSE
      )
    $function$
  `;
  await sql`
    REVOKE ALL ON FUNCTION omni_active_memory_lineage_owned_by(
      TEXT,
      TEXT,
      TEXT[]
    ) FROM PUBLIC
  `;
  await sql`
    DO $migration$
    BEGIN
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'omni_runtime') THEN
        GRANT EXECUTE ON FUNCTION omni_active_memory_lineage_owned_by(
          TEXT,
          TEXT,
          TEXT[]
        ) TO omni_runtime;
      END IF;
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'omni_maintenance') THEN
        GRANT EXECUTE ON FUNCTION omni_active_memory_lineage_owned_by(
          TEXT,
          TEXT,
          TEXT[]
        ) TO omni_maintenance;
      END IF;
    END
    $migration$
  `;
  await sql`
    DO $migration$
    BEGIN
      IF NOT EXISTS (
        SELECT 1
        FROM pg_proc procedure
        JOIN pg_namespace namespace ON namespace.oid = procedure.pronamespace
        WHERE procedure.proname = 'omni_active_memory_lineage_owned_by'
          AND namespace.nspname = current_schema()
          AND procedure.prosecdef
          AND procedure.provolatile = 's'
          AND pg_get_function_identity_arguments(procedure.oid) =
            'row_tenant_id text, row_owner_actor_id text, row_memory_ids text[]'
      ) THEN
        RAISE EXCEPTION 'Entity memory lineage owner probe is invalid'
          USING ERRCODE = '55000';
      END IF;
    END
    $migration$
  `;
}

async function ensureEntityRegistryIdentityTriggerDispatch(sql: SqlClient) {
  await sql`
    CREATE OR REPLACE FUNCTION omni_reject_entity_registry_identity_change()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    AS $function$
    BEGIN
      IF TG_TABLE_NAME = 'omni_entity_records' THEN
        IF ROW(
          OLD.tenant_id, OLD.id, OLD.owner_actor_id, OLD.ontology_version_id,
          OLD.entity_type_id, OLD.normalized_label_sha256,
          OLD.access_scope_sha256, OLD.created_at
        ) IS DISTINCT FROM ROW(
          NEW.tenant_id, NEW.id, NEW.owner_actor_id, NEW.ontology_version_id,
          NEW.entity_type_id, NEW.normalized_label_sha256,
          NEW.access_scope_sha256, NEW.created_at
        ) THEN
          RAISE EXCEPTION 'Entity identity and access scope are immutable'
            USING ERRCODE = '55000';
        END IF;
        IF OLD.canonical_label IS DISTINCT FROM NEW.canonical_label
          AND NOT (
            OLD.state <> 'retired'
            AND NEW.state = 'retired'
            AND NEW.canonical_label = '[forgotten]'
          )
        THEN
          RAISE EXCEPTION 'Entity labels may only be scrubbed on retirement'
            USING ERRCODE = '55000';
        END IF;
      ELSIF TG_TABLE_NAME = 'omni_entity_aliases' THEN
        IF ROW(
          OLD.tenant_id, OLD.id, OLD.owner_actor_id, OLD.entity_id,
          OLD.normalized_alias_sha256, OLD.access_scope_sha256, OLD.created_at
        ) IS DISTINCT FROM ROW(
          NEW.tenant_id, NEW.id, NEW.owner_actor_id, NEW.entity_id,
          NEW.normalized_alias_sha256, NEW.access_scope_sha256, NEW.created_at
        ) THEN
          RAISE EXCEPTION 'Entity alias identity and access scope are immutable'
            USING ERRCODE = '55000';
        END IF;
      ELSE
        RAISE EXCEPTION 'Entity identity trigger is attached to an invalid relation'
          USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END
    $function$
  `;
  await sql`
    DO $migration$
    BEGIN
      IF (
        SELECT count(*)
        FROM pg_trigger
        WHERE tgname IN (
          'omni_entity_records_identity_immutable',
          'omni_entity_aliases_identity_immutable'
        )
          AND tgrelid IN (
            'omni_entity_records'::regclass,
            'omni_entity_aliases'::regclass
          )
          AND NOT tgisinternal
          AND tgenabled = 'O'
      ) <> 2 THEN
        RAISE EXCEPTION 'Entity identity trigger dispatch is invalid'
          USING ERRCODE = '55000';
      END IF;
    END
    $migration$
  `;
}

async function ensureEntityEvidenceLineageBarrier(sql: SqlClient) {
  await sql`
    ALTER TABLE omni_entity_records
    ADD COLUMN IF NOT EXISTS lineage_evidence_unit_ids TEXT[] NOT NULL DEFAULT '{}'
  `;
  await sql`
    ALTER TABLE omni_entity_aliases
    ADD COLUMN IF NOT EXISTS lineage_evidence_unit_ids TEXT[] NOT NULL DEFAULT '{}'
  `;
  await sql`
    UPDATE omni_entity_records record
    SET lineage_evidence_unit_ids = CASE
      WHEN record.state = 'retired' THEN '{}'::TEXT[]
      ELSE COALESCE((
        SELECT array_agg(
          DISTINCT reference ->> 'referenceId'
          ORDER BY reference ->> 'referenceId'
        )
        FROM jsonb_array_elements(record.contract -> 'lineage') reference
        WHERE reference ->> 'kind' = 'evidence_unit'
      ), '{}'::TEXT[])
    END
  `;
  await sql`
    UPDATE omni_entity_aliases alias
    SET lineage_evidence_unit_ids = CASE
      WHEN alias.state = 'active'
        AND alias.contract #>> '{lineage,kind}' = 'evidence_unit'
      THEN ARRAY[alias.contract #>> '{lineage,referenceId}']
      ELSE '{}'::TEXT[]
    END
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_entity_records_evidence_lineage_idx
    ON omni_entity_records USING GIN (lineage_evidence_unit_ids)
  `;
  await sql`
    CREATE INDEX IF NOT EXISTS omni_entity_aliases_evidence_lineage_idx
    ON omni_entity_aliases USING GIN (lineage_evidence_unit_ids)
  `;

  await sql`
    CREATE OR REPLACE FUNCTION omni_active_evidence_lineage_owned_by(
      row_tenant_id TEXT,
      row_owner_actor_id TEXT,
      row_evidence_unit_ids TEXT[]
    )
    RETURNS BOOLEAN
    LANGUAGE SQL
    STABLE
    SECURITY DEFINER
    SET search_path = pg_catalog, public
    AS $function$
      SELECT COALESCE(
        public.omni_current_tenant() = row_tenant_id
        AND public.omni_actor_scope_v1_allows(
          row_tenant_id,
          row_owner_actor_id
        )
        AND cardinality(row_evidence_unit_ids) BETWEEN 1 AND 64
        AND cardinality(ARRAY(
          SELECT DISTINCT evidence_unit_id COLLATE "C"
          FROM unnest(row_evidence_unit_ids) evidence_unit_id
          ORDER BY evidence_unit_id COLLATE "C"
        )) = cardinality(row_evidence_unit_ids)
        AND (
          SELECT count(*)
          FROM public.omni_evidence_units evidence
          JOIN public.omni_source_items source_item
            ON source_item.tenant_id = evidence.tenant_id
           AND source_item.id = evidence.source_item_id
           AND source_item.current_revision_id = evidence.source_revision_id
          LEFT JOIN public.omni_source_sync_heads source_head
            ON source_head.tenant_id = evidence.tenant_id
           AND source_head.source_item_id = evidence.source_item_id
          WHERE evidence.tenant_id = row_tenant_id
            AND evidence.owner_actor_id = row_owner_actor_id
            AND evidence.id = ANY(row_evidence_unit_ids)
            AND evidence.visibility = 'user_private'
            AND evidence.workspace_id IS NULL
            AND evidence.project_id IS NULL
            AND evidence.mission_id IS NULL
            AND evidence.allowed_purpose_ids @> ARRAY[
              'agent.answer.claim-evidence-verification'
            ]::TEXT[]
            AND (
              evidence.retention_expires_at IS NULL
              OR evidence.retention_expires_at > CURRENT_TIMESTAMP
            )
            AND source_item.owner_actor_id = row_owner_actor_id
            AND source_item.visibility = 'user_private'
            AND source_item.workspace_id IS NULL
            AND source_item.project_id IS NULL
            AND source_item.mission_id IS NULL
            AND (
              source_item.retention_expires_at IS NULL
              OR source_item.retention_expires_at > CURRENT_TIMESTAMP
            )
            AND (
              source_head.source_item_id IS NULL
              OR (
                source_head.operation = 'upsert'
                AND NOT source_head.absence_observed
                AND source_head.source_revision_id = evidence.source_revision_id
                AND source_head.source_tombstone_id IS NULL
              )
            )
        ) = cardinality(row_evidence_unit_ids),
        FALSE
      )
    $function$
  `;
  await sql`
    REVOKE ALL ON FUNCTION omni_active_evidence_lineage_owned_by(
      TEXT,
      TEXT,
      TEXT[]
    ) FROM PUBLIC
  `;
  await sql`
    DO $migration$
    BEGIN
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'omni_runtime') THEN
        GRANT EXECUTE ON FUNCTION omni_active_evidence_lineage_owned_by(
          TEXT,
          TEXT,
          TEXT[]
        ) TO omni_runtime;
      END IF;
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'omni_maintenance') THEN
        GRANT EXECUTE ON FUNCTION omni_active_evidence_lineage_owned_by(
          TEXT,
          TEXT,
          TEXT[]
        ) TO omni_maintenance;
      END IF;
    END
    $migration$
  `;

  await sql`
    CREATE OR REPLACE FUNCTION omni_validate_entity_evidence_lineage()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    AS $function$
    DECLARE
      contract_evidence_ids TEXT[];
    BEGIN
      IF TG_TABLE_NAME = 'omni_entity_records' THEN
        contract_evidence_ids := CASE
          WHEN NEW.state = 'retired' THEN '{}'::TEXT[]
          ELSE COALESCE((
            SELECT array_agg(
              DISTINCT reference ->> 'referenceId'
              ORDER BY reference ->> 'referenceId'
            )
            FROM jsonb_array_elements(NEW.contract -> 'lineage') reference
            WHERE reference ->> 'kind' = 'evidence_unit'
          ), '{}'::TEXT[])
        END;
      ELSIF TG_TABLE_NAME = 'omni_entity_aliases' THEN
        contract_evidence_ids := CASE
          WHEN NEW.state = 'active'
            AND NEW.contract #>> '{lineage,kind}' = 'evidence_unit'
          THEN ARRAY[NEW.contract #>> '{lineage,referenceId}']
          ELSE '{}'::TEXT[]
        END;
      ELSE
        RAISE EXCEPTION 'Entity evidence trigger is attached to an invalid relation'
          USING ERRCODE = '55000';
      END IF;

      IF NEW.lineage_evidence_unit_ids IS DISTINCT FROM contract_evidence_ids THEN
        RAISE EXCEPTION 'Entity evidence lineage index does not match its contract'
          USING ERRCODE = '23514';
      END IF;
      IF cardinality(contract_evidence_ids) > 0
        AND NOT omni_active_evidence_lineage_owned_by(
          NEW.tenant_id,
          NEW.owner_actor_id,
          contract_evidence_ids
        )
      THEN
        RAISE EXCEPTION 'Entity lineage references inactive or inaccessible evidence'
          USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END
    $function$
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_entity_records_evidence_lineage_barrier
    ON omni_entity_records
  `;
  await sql`
    CREATE TRIGGER omni_entity_records_evidence_lineage_barrier
    BEFORE INSERT OR UPDATE OF state, lineage_evidence_unit_ids, contract
    ON omni_entity_records
    FOR EACH ROW EXECUTE FUNCTION omni_validate_entity_evidence_lineage()
  `;
  await sql`
    DROP TRIGGER IF EXISTS omni_entity_aliases_evidence_lineage_barrier
    ON omni_entity_aliases
  `;
  await sql`
    CREATE TRIGGER omni_entity_aliases_evidence_lineage_barrier
    BEFORE INSERT OR UPDATE OF state, lineage_evidence_unit_ids, contract
    ON omni_entity_aliases
    FOR EACH ROW EXECUTE FUNCTION omni_validate_entity_evidence_lineage()
  `;

  await sql`
    DROP POLICY IF EXISTS omni_entity_evidence_lineage_barrier
    ON omni_entity_records
  `;
  await sql`
    CREATE POLICY omni_entity_evidence_lineage_barrier
    ON omni_entity_records
    AS RESTRICTIVE
    FOR SELECT
    USING (
      cardinality(lineage_evidence_unit_ids) = 0
      OR omni_system_scope_enabled()
      OR omni_active_evidence_lineage_owned_by(
        tenant_id,
        owner_actor_id,
        lineage_evidence_unit_ids
      )
    )
  `;
  await sql`
    DROP POLICY IF EXISTS omni_entity_evidence_lineage_barrier
    ON omni_entity_aliases
  `;
  await sql`
    CREATE POLICY omni_entity_evidence_lineage_barrier
    ON omni_entity_aliases
    AS RESTRICTIVE
    FOR SELECT
    USING (
      cardinality(lineage_evidence_unit_ids) = 0
      OR omni_system_scope_enabled()
      OR omni_active_evidence_lineage_owned_by(
        tenant_id,
        owner_actor_id,
        lineage_evidence_unit_ids
      )
    )
  `;

  await sql`
    DO $migration$
    BEGIN
      IF EXISTS (
        SELECT 1
        FROM omni_entity_records record
        WHERE record.lineage_evidence_unit_ids IS DISTINCT FROM CASE
          WHEN record.state = 'retired' THEN '{}'::TEXT[]
          ELSE COALESCE((
            SELECT array_agg(
              DISTINCT reference ->> 'referenceId'
              ORDER BY reference ->> 'referenceId'
            )
            FROM jsonb_array_elements(record.contract -> 'lineage') reference
            WHERE reference ->> 'kind' = 'evidence_unit'
          ), '{}'::TEXT[])
        END
      ) OR EXISTS (
        SELECT 1
        FROM omni_entity_aliases alias
        WHERE alias.lineage_evidence_unit_ids IS DISTINCT FROM CASE
          WHEN alias.state = 'active'
            AND alias.contract #>> '{lineage,kind}' = 'evidence_unit'
          THEN ARRAY[alias.contract #>> '{lineage,referenceId}']
          ELSE '{}'::TEXT[]
        END
      ) OR (
        SELECT count(*)
        FROM pg_policy
        WHERE polname = 'omni_entity_evidence_lineage_barrier'
          AND polrelid IN (
            'omni_entity_records'::regclass,
            'omni_entity_aliases'::regclass
          )
          AND NOT polpermissive
          AND polcmd = 'r'
      ) <> 2 OR (
        SELECT count(*)
        FROM pg_trigger
        WHERE tgname IN (
          'omni_entity_records_evidence_lineage_barrier',
          'omni_entity_aliases_evidence_lineage_barrier'
        )
          AND NOT tgisinternal
      ) <> 2 THEN
        RAISE EXCEPTION 'Entity evidence lineage barrier is invalid'
          USING ERRCODE = '55000';
      END IF;
    END
    $migration$
  `;
}

